@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeSuggestionsSuite(Suite):
    """Parity suite for M27: did-you-mean suggestion ranking and formatting.

    Verifies `best_matches` and `pretty_seq` produce identical results
    between the pure-Python difflib path and the Rust Ratcliff-Obershelp
    path when the `native_type_kernel` gate is on.
    """

    def setUp(self) -> None:
        from mypy.messages import _set_native_suggestions_active

        self._setter = _set_native_suggestions_active

    def _check_best_matches(
        self, current: str, options: list[str], n: int
    ) -> None:
        from mypy.messages import best_matches

        self._setter(False)
        py_result = best_matches(current, options, n)
        self._setter(True)
        rs_result = best_matches(current, options, n)
        assert_equal(
            rs_result,
            py_result,
            f"best_matches({current!r}, {options!r}, {n})",
        )

    def _check_pretty_seq(self, args: list[str], conjunction: str) -> None:
        from mypy.messages import pretty_seq

        self._setter(False)
        py_result = pretty_seq(args, conjunction)
        self._setter(True)
        rs_result = pretty_seq(args, conjunction)
        assert_equal(
            rs_result,
            py_result,
            f"pretty_seq({args!r}, {conjunction!r})",
        )

    def test_best_matches_identical(self) -> None:
        self._check_best_matches("foo", ["foo", "bar", "baz"], 3)

    def test_best_matches_fuzzy(self) -> None:
        self._check_best_matches(
            "helo", ["hello", "help", "hero", "hola", "foo"], 3
        )

    def test_best_matches_empty_current(self) -> None:
        self._check_best_matches("", ["a", "b"], 3)

    def test_best_matches_no_matches(self) -> None:
        self._check_best_matches("xyz", ["foo", "bar", "baz"], 3)

    def test_best_matches_many_options(self) -> None:
        options = [f"test{i}" for i in range(60)]
        options[30] = "test"
        self._check_best_matches("test", options, 3)

    def test_best_matches_tie_breaking(self) -> None:
        self._check_best_matches(
            "abc",
            ["abd", "abe", "abf", "abg"],
            2,
        )

    def test_best_matches_partial_match(self) -> None:
        self._check_best_matches(
            "append",
            ["apend", "append", "prepend", "foo"],
            3,
        )

    def test_best_matches_case_sensitive(self) -> None:
        self._check_best_matches(
            "Sequence", ["sequence", "Sequence", "SEQUENCE"], 3
        )

    def test_best_matches_n_larger_than_results(self) -> None:
        self._check_best_matches("foo", ["foo", "foobar"], 10)

    def test_pretty_seq_single(self) -> None:
        self._check_pretty_seq(["a"], "or")

    def test_pretty_seq_pair(self) -> None:
        self._check_pretty_seq(["a", "b"], "or")

    def test_pretty_seq_triple(self) -> None:
        self._check_pretty_seq(["a", "b", "c"], "or")

    def test_pretty_seq_quad(self) -> None:
        self._check_pretty_seq(["a", "b", "c", "d"], "and")

    def test_pretty_seq_empty(self) -> None:
        self._setter(False)
        from mypy.messages import pretty_seq

        # Python crashes on empty, so only test Rust returns ""
        self._setter(True)
        assert_equal(pretty_seq([], "or"), "")

    def test_pretty_seq_and_conjunction(self) -> None:
        self._check_pretty_seq(["x", "y", "z"], "and")


# Stage 6b parity suite: compares Python vs Rust format-string parsing.
# Gated by TEST_NATIVE_TYPE_KERNEL=1 plus the type_kernel extension.
try:
    import type_kernel as _strformat_type_kernel  # noqa: F401

    _HAS_TYPE_KERNEL_STRFORMAT_TEST = True
except ImportError:
    _HAS_TYPE_KERNEL_STRFORMAT_TEST = False

_NATIVE_STRFORMAT_ENABLED = (
    bool(os.environ.get("TEST_NATIVE_TYPE_KERNEL"))
    and _HAS_TYPE_KERNEL_STRFORMAT_TEST
)


@skipUnless(
    _NATIVE_STRFORMAT_ENABLED,
    "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext",
)
class NativeStrFormatSuite(Suite):
    """Parity tests for Rust format-string parsing (Stage 6b).

    Each test toggles `_native_strformat_active` and compares the Rust
    output against the Python output for `parse_conversion_specifiers`,
    `find_non_escaped_targets`, and `parse_format_value`.
    """

    def setUp(self) -> None:
        from mypy.checkstrformat import (
            _set_native_strformat_active,
            find_non_escaped_targets,
            parse_conversion_specifiers,
            parse_format_value,
        )
        from mypy.errors import Errors
        from mypy.messages import MessageBuilder
        from mypy.options import Options

        self._set_active = _set_native_strformat_active
        self._parse_conv = parse_conversion_specifiers
        self._parse_fmt = parse_format_value
        self._find_targets = find_non_escaped_targets
        self._errors = Errors(Options())
        self._msg = MessageBuilder(self._errors, None)  # type: ignore[arg-type]

    def _spec_tuples(self, specs: list[ConversionSpecifier]) -> list[tuple]:  # type: ignore[type-arg]
        """Convert ConversionSpecifier list to comparable tuples."""
        return [
            (
                s.whole_seq,
                s.start_pos,
                s.key,
                s.conv_type,
                s.flags,
                s.width,
                s.precision,
                s.format_spec,
                s.non_standard_format_spec,
                s.conversion,
                s.field,
            )
            for s in specs
        ]

    # --- parse_conversion_specifiers ---

    def test_parse_conv_simple(self) -> None:
        for s in ["%s", "%d", "%f", "%x", "%%", "%r"]:
            self._set_active(False)
            py = self._spec_tuples(self._parse_conv(s))
            self._set_active(True)
            rs = self._spec_tuples(self._parse_conv(s))
            assert_equal(rs, py, f"mismatch for {s!r}")

    def test_parse_conv_multiple(self) -> None:
        for s in ["%d %s", "%s %d %f", "hello %s world %d", "%d%%", "100%% done"]:
            self._set_active(False)
            py = self._spec_tuples(self._parse_conv(s))
            self._set_active(True)
            rs = self._spec_tuples(self._parse_conv(s))
            assert_equal(rs, py, f"mismatch for {s!r}")

    def test_parse_conv_with_key(self) -> None:
        for s in ["%(name)s", "%(key)d %(other)s", "%(x)f"]:
            self._set_active(False)
            py = self._spec_tuples(self._parse_conv(s))
            self._set_active(True)
            rs = self._spec_tuples(self._parse_conv(s))
            assert_equal(rs, py, f"mismatch for {s!r}")

    def test_parse_conv_flags_width_precision(self) -> None:
        cases = [
            "%05d", "%-10s", "%+d", "%#x", "%*d", "%.*f",
            "%10.2f", "%-+5.3e", "% #0*d", "%8.0f",
            "%5d", "%.3s", "%5.3f",
        ]
        for s in cases:
            self._set_active(False)
            py = self._spec_tuples(self._parse_conv(s))
            self._set_active(True)
            rs = self._spec_tuples(self._parse_conv(s))
            assert_equal(rs, py, f"mismatch for {s!r}")

    def test_parse_conv_no_specifiers(self) -> None:
        for s in ["hello", "", "no percent", "100 percent no sign"]:
            self._set_active(False)
            py = self._spec_tuples(self._parse_conv(s))
            self._set_active(True)
            rs = self._spec_tuples(self._parse_conv(s))
            assert_equal(rs, py, f"mismatch for {s!r}")

    # --- find_non_escaped_targets ---

    def test_find_targets_basic(self) -> None:
        from mypy.nodes import Context

        ctx = Context()
        cases = [
            "{}", "{name}", "{0}", "{0:d}", "{name!r}", "{{escaped}}",
            "no targets", "", "{a} {b}", "{0}{1}{2}",
            "{:.2f}", "{:>10}", "{:s}", "{!s}",
        ]
        for s in cases:
            self._set_active(False)
            py = self._find_targets(s, ctx, self._msg)
            self._set_active(True)
            rs = self._find_targets(s, ctx, self._msg)
            assert_equal(rs, py, f"mismatch for {s!r}")

    def test_find_targets_errors(self) -> None:
        from mypy.nodes import Context

        ctx = Context()
        # Clear errors between runs
        for s in ["}", "{", "{}}", "{{}"]:
            self._errors.reset()
            self._set_active(False)
            py = self._find_targets(s, ctx, self._msg)
            self._errors.reset()
            self._set_active(True)
            rs = self._find_targets(s, ctx, self._msg)
            assert_equal(rs, py, f"mismatch for {s!r}")

    # --- parse_format_value ---

    def test_parse_format_value_basic(self) -> None:
        from mypy.nodes import Context

        ctx = Context()
        cases = [
            "{}", "{0}", "{name}", "{:s}", "{:d}", "{:.2f}",
            "{:>10}", "{!r}", "{!s}", "{0:d} {1:s}",
            "{{literal}}", "no specs", "",
            "{name!r:>{width}}",
        ]
        for s in cases:
            self._errors.reset()
            self._set_active(False)
            py = self._parse_fmt(s, ctx, self._msg)
            self._errors.reset()
            self._set_active(True)
            rs = self._parse_fmt(s, ctx, self._msg)
            assert_equal(
                self._spec_tuples(rs) if rs else None,
                self._spec_tuples(py) if py else None,
                f"mismatch for {s!r}",
            )

    def test_parse_format_value_errors(self) -> None:
        from mypy.nodes import Context

        ctx = Context()
        for s in ["}", "{", "{a}{", "{a}}"]:
            self._errors.reset()
            self._set_active(False)
            py = self._parse_fmt(s, ctx, self._msg)
            self._errors.reset()
            self._set_active(True)
            rs = self._parse_fmt(s, ctx, self._msg)
            assert_equal(rs, py, f"mismatch for {s!r}")


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeMessagesSuite(Suite):
    """Parity tests for the Rust message formatting (M21).

    Each test builds a NativeTypeResolver from the live Python TypeInfo
    graph, serializes a `Type` via `Type.write(WriteBuffer)`, and asserts
    that `rust_format_type_bare(bytes, resolver, ...)` matches the
    pure-Python `format_type_bare(typ, options, ...)`. The corpus targets
    the hot type-formatter output that appears in error messages.
    """

    def setUp(self) -> None:
        from mypy.options import Options
        from mypy.test.typefixture import TypeFixture as _TypeFixture

        self.fx = _TypeFixture()
        self.options = Options()
        type_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.ci,
            self.fx.di,
            self.fx.ei,
            self.fx.e2i,
            self.fx.e3i,
            self.fx.fi,
            self.fx.f2i,
            self.fx.f3i,
            self.fx.gi,
            self.fx.g2i,
            self.fx.hi,
            self.fx.gsi,
            self.fx.gs2i,
            self.fx.std_tuplei,
            self.fx.std_listi,
            self.fx.type_typei,
            self.fx.bool_type_info,
            self.fx.str_type_info,
            self.fx.functioni,
        ]
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])

    def _bytes_of(self, t: Type) -> bytes:
        buf = _WriteBuffer()
        t.write(buf)
        return buf.getvalue()

    def assert_format_par(self, t: Type, verbosity: int = 0) -> None:
        from mypy.messages import format_type_bare

        expected = format_type_bare(t, self.options, verbosity=verbosity)
        actual = _type_kernel.rust_format_type_bare(
            self._bytes_of(t), self.resolver, verbosity, False, True
        )
        self.assertIsNotNone(actual, f"rust format_type_bare({t!r}) returned None")
        assert_equal(actual, expected, f"format_type_bare({t!r}) = {{}} ({{}} expected)")

    def assert_format_quoted_par(self, t: Type) -> None:
        from mypy.messages import format_type

        expected = format_type(t, self.options)
        actual = _type_kernel.rust_format_type(self._bytes_of(t), self.resolver, 0, False, True)
        self.assertIsNotNone(actual, f"rust format_type({t!r}) returned None")
        assert_equal(actual, expected, f"format_type({t!r}) = {{}} ({{}} expected)")

    def test_pure_helpers(self) -> None:
        # Pure string helpers, no resolver needed.
        assert_equal(_type_kernel.rust_quote_type_string("int"), '"int"')
        assert_equal(_type_kernel.rust_quote_type_string("Module"), "Module")
        assert_equal(_type_kernel.rust_capitalize("hello"), "Hello")
        assert_equal(_type_kernel.rust_capitalize(""), "")
        assert_equal(
            _type_kernel.rust_pretty_seq(["a", "b"], "or"),
            '"a" or "b"',
        )
        assert_equal(
            _type_kernel.rust_format_string_list(["a", "b", "c"]),
            "a, b and c",
        )
        assert_equal(
            _type_kernel.rust_format_item_name_list(["a", "b"]),
            '("a", "b")',
        )
        assert_equal(
            _type_kernel.rust_wrong_type_arg_count(1, 1, "0", "List"),
            '"List" expects 1 type argument, but none given',
        )
        assert_equal(_type_kernel.rust_strip_quotes('"x"'), "x")
        assert_equal(_type_kernel.rust_extract_type('"__getitem__" of list'), "list")
        assert_equal(_type_kernel.rust_variance_string(1), "covariant")
        assert_equal(_type_kernel.rust_variance_string(2), "contravariant")
        assert_equal(_type_kernel.rust_variance_string(0), "invariant")

    def test_any(self) -> None:

        t = AnyType(TypeOfAny.special_form)
        self.assert_format_par(t)
        self.assert_format_quoted_par(t)

    def test_none(self) -> None:
        self.assert_format_par(NoneType())
        self.assert_format_quoted_par(NoneType())

    def test_uninhabited(self) -> None:
        self.assert_format_par(UninhabitedType())

    def test_instance_singletons(self) -> None:
        self.assert_format_par(self.fx.str_type)
        self.assert_format_par(self.fx.function)
        self.assert_format_par(self.fx.bool_type)
        self.assert_format_par(self.fx.o)
        self.assert_format_par(self.fx.a)
        self.assert_format_par(self.fx.b)
        self.assert_format_par(self.fx.o)

    def test_instance_generic(self) -> None:
        self.assert_format_par(self.fx.ga)
        self.assert_format_par(self.fx.gb)
        self.assert_format_par(self.fx.gt)
        self.assert_format_par(self.fx.lsta)
        self.assert_format_par(self.fx.lstb)

    def test_instance_tuple(self) -> None:
        self.assert_format_par(self.fx.std_tuple)

    def test_literal_int(self) -> None:
        self.assert_format_par(self.fx.lit1)
        self.assert_format_par(self.fx.lit2)
        self.assert_format_par(self.fx.lit4)

    def test_literal_str(self) -> None:
        self.assert_format_par(self.fx.lit_str1)
        self.assert_format_par(self.fx.lit_str2)
        self.assert_format_par(self.fx.lit_str3)

    def test_literal_bool(self) -> None:
        self.assert_format_par(self.fx.lit_false)
        self.assert_format_par(self.fx.lit_true)

    def test_type_type(self) -> None:
        self.assert_format_par(self.fx.type_a)
        self.assert_format_par(self.fx.type_b)
        self.assert_format_par(self.fx.type_any)

    def test_union_none(self) -> None:
        # Optional[T]: should format as `T | None`.
        u = UnionType.make_union([self.fx.a, NoneType()])
        self.assert_format_par(u)
        self.assert_format_quoted_par(u)

    def test_union_multi(self) -> None:
        u = UnionType.make_union([self.fx.a, self.fx.b, self.fx.o])
        self.assert_format_par(u)

    def test_union_literals(self) -> None:
        # Coalesced Literal[1, 2] | None.
        u = UnionType.make_union([self.fx.lit1, self.fx.lit2, NoneType()])
        self.assert_format_par(u)

    def test_callable_simple(self) -> None:
        c = CallableType(
            [self.fx.a, self.fx.b],
            [ARG_POS, ARG_POS],
            [None, None],
            self.fx.o,
            self.fx.function,
        )
        self.assert_format_par(c)

    def test_callable_named(self) -> None:
        # Named-arg callables use pretty_callable, which needs FuncDef
        # data not present in the wire format, so the Rust path defers
        # (returns None) and Python formats instead.
        c = CallableType(
            [self.fx.a],
            [ARG_NAMED],
            ["x"],
            self.fx.o,
            self.fx.function,
        )
        actual = _type_kernel.rust_format_type_bare(
            self._bytes_of(c), self.resolver, 0, False, True
        )
        self.assertIsNone(actual, "named-arg callable should defer to Python")

    def test_ellipsis_callable(self) -> None:
        c = CallableType(
            [],
            [],
            [],
            self.fx.o,
            self.fx.function,
            is_ellipsis_args=True,
        )
        self.assert_format_par(c)

    def test_tuple_type(self) -> None:
        t = TupleType([self.fx.a, self.fx.b], self.fx.std_tuple)
        self.assert_format_par(t)

    def test_type_var(self) -> None:
        self.assert_format_par(self.fx.t)
        self.assert_format_par(self.fx.tf)

    def test_unpack(self) -> None:
        u = UnpackType(self.fx.a)
        self.assert_format_par(u)

    def test_typeddict_anonymous(self) -> None:
        from mypy.types import TypedDictType

        # Create a TypeInfo for typing._TypedDict so the anonymity check
        # treats the fallback as anonymous.
        fb_ti = self.fx.make_type_info("typing._TypedDict")
        fb = Instance(fb_ti, [])
        t = TypedDictType(
            {"x": self.fx.a, "y": self.fx.b},
            {"x"},
            set(),
            fb,
        )
        self.assert_format_par(t)

    def test_deleted_type(self) -> None:
        from mypy.types import DeletedType

        t = DeletedType("var")
        self.assert_format_par(t)

    def test_append_invariance_notes_par(self) -> None:
        from mypy.messages import append_invariance_notes

        for arg_t, exp_t in [
            (self.fx.lsta, self.fx.lsta),  # List[A] vs List[A]: list note fires
            (self.fx.lsta, self.fx.lstb),  # A not subtype of B: no note appended
        ]:
            expected = append_invariance_notes([], arg_t, exp_t)
            actual = _type_kernel.rust_append_invariance_notes(
                self._bytes_of(arg_t), self._bytes_of(exp_t), self.resolver
            )
            self.assertIsNotNone(actual, f"rust invariance notes deferred for {arg_t} vs {exp_t}")
            assert_equal(actual, expected, f"invariance notes mismatch {arg_t} vs {exp_t}")

    def test_append_numbers_notes_par(self) -> None:
        from mypy.messages import append_numbers_notes

        num_t = Instance(self.fx.make_type_info("numbers.Complex"), [])
        for exp_t in [num_t, self.fx.str_type]:
            expected = append_numbers_notes([], self.fx.a, exp_t)
            actual = _type_kernel.rust_append_numbers_notes(self._bytes_of(exp_t))
            self.assertIsNotNone(actual, f"rust numbers notes deferred for {exp_t}")
            assert_equal(actual, expected, f"numbers notes mismatch for {exp_t}")

    def test_append_union_note_par(self) -> None:
        from mypy.messages import append_union_note

        # 11 items clears MAX_UNION_ITEMS so the non-matching tail can fire.
        items = [self.fx.a, self.fx.b, self.fx.c, self.fx.d, self.fx.e, self.fx.f,
                 self.fx.e2, self.fx.e3, self.fx.o, self.fx.str_type, self.fx.bool_type]
        arg_u = UnionType.make_union(items)
        exp_u = UnionType.make_union([self.fx.a, self.fx.b])
        expected = append_union_note(
            [],
            arg_u,  # type: ignore[arg-type]
            exp_u,  # type: ignore[arg-type]
            self.options,
        )
        actual = _type_kernel.rust_append_union_note(
            self._bytes_of(arg_u),
            self._bytes_of(exp_u),
            self.resolver,
            self.options.use_star_unpack(),
        )
        if actual is not None:
            assert_equal(actual, expected, "union note mismatch")

    def test_pretty_callable_par(self) -> None:
        from mypy.messages import pretty_callable

        # Definition-free callable, the exact scope of the Rust gate.
        c = CallableType(
            [self.fx.a, self.fx.b],
            [ARG_POS, ARG_POS],
            [None, None],
            self.fx.o,
            self.fx.function,
            name="f",
        )
        expected = pretty_callable(c, self.options)
        actual = _type_kernel.rust_pretty_callable(
            self._bytes_of(c), self.resolver, False, self.options.use_star_unpack()
        )
        self.assertIsNotNone(actual, "rust pretty_callable deferred on a plain callable")
        assert_equal(actual, expected, "pretty_callable mismatch")


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeMessagesDeferralSuite(Suite):
    """Gate-on/off differential for the messages.rs deferral ports.

    `rust_format_type_distinctly` mirrors `format_type_distinctly`, including
    the `min_verbosity` decision for a Callable/Callable pair where `right` has
    named args: Python bumps verbosity to 1 iff
    `is_subtype(left, right, ignore_pos_arg_names=True)`, and the Rust seam now
    computes that natively (previously it deferred the whole branch whenever
    `right` had any named args).

    Each test compares the gate-off (pure-Python) and gate-on (Rust seam) results
    of `format_type_distinctly` for representative pairs and asserts parity. Named-
    arg callables still defer at the format step (pretty_callable needs FuncDef
    data the wire cannot carry), so both gates resolve through Python there; the
    differential guards against a regression while the Rust unit tests prove the
    decision logic itself.
    """

    def setUp(self) -> None:
        from mypy.messages import _set_native_messages_active, _set_native_messages_resolver
        from mypy.options import Options
        from mypy.test.typefixture import TypeFixture as _TypeFixture

        self.fx = _TypeFixture()
        self.options = Options()
        self._set_active = _set_native_messages_active
        self._set_resolver = _set_native_messages_resolver
        self._buf = _WriteBuffer()
        type_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.ci,
            self.fx.functioni,
        ]
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        self._set_resolver(self.resolver)
        self._set_active(True)

    def tearDown(self) -> None:
        self._set_active(False)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _bytes_of(self, t: Type) -> bytes:
        self._buf = _WriteBuffer()
        t.write(self._buf)
        return self._buf.getvalue()

    def _assert_distinctly_par(self, *types: Type) -> None:
        from mypy.messages import format_type_distinctly

        off = self._with_gate(
            False,
            lambda: format_type_distinctly(*types, options=self.options, bare=True),
        )
        on = self._with_gate(
            True,
            lambda: format_type_distinctly(*types, options=self.options, bare=True),
        )
        assert_equal(on, off, f"format_type_distinctly parity {types}")

    def test_positional_callables(self) -> None:
        # Plain positional callables: the common formattable path (no
        # pretty_callable detour), both gates must agree.
        left = CallableType(
            [self.fx.a, self.fx.b],
            [ARG_POS, ARG_POS],
            [None, None],
            self.fx.o,
            self.fx.function,
        )
        right = CallableType(
            [self.fx.c],
            [ARG_POS],
            [None],
            self.fx.o,
            self.fx.function,
        )
        self._assert_distinctly_par(left, right)

    def test_callable_pair_named_arg_non_subtype(self) -> None:
        # left arg A, right arg B (unrelated): is_subtype is False, so the
        # min_verbosity decision resolves to 0 natively. Previously the seam
        # deferred this whole branch; gate-on must still match gate-off.
        left = CallableType(
            [self.fx.a],
            [ARG_POS],
            [None],
            self.fx.o,
            self.fx.function,
        )
        right = CallableType(
            [self.fx.b],
            [ARG_NAMED],
            ["x"],
            self.fx.o,
            self.fx.function,
        )
        self._assert_distinctly_par(left, right)

    def test_callable_pair_named_arg_subtype(self) -> None:
        # Identical object args with a named arg: is_subtype(left, right,
        # ignore_pos_arg_names=True) is True, so min_verbosity resolves to 1
        # natively (matching Python's verbosity bump).
        left = CallableType(
            [self.fx.o],
            [ARG_NAMED],
            ["x"],
            self.fx.o,
            self.fx.function,
        )
        right = CallableType(
            [self.fx.o],
            [ARG_NAMED],
            ["x"],
            self.fx.o,
            self.fx.function,
        )
        self._assert_distinctly_par(left, right)

    def test_single_instance_pair(self) -> None:
        # Non-callable pair: the decision is trivially verbosity 0 natively.
        self._assert_distinctly_par(self.fx.a, self.fx.b)

    def test_mixed_callable_instance(self) -> None:
        # One callable, one instance: no verbosity bump, must stay in parity.
        c = CallableType(
            [self.fx.a],
            [ARG_POS],
            [None],
            self.fx.o,
            self.fx.function,
        )
        self._assert_distinctly_par(c, self.fx.b)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeFindTypeOverlapsSuite(Suite):
    """Parity tests for the Rust find_type_overlaps port (mypy.messages).

    find_type_overlaps(*types) returns the set of fullnames whose short
    names collide across the given types (plus the typing.* injections for
    TYPES_FOR_UNIMPORTED_HINTS). The Rust seam (rust_find_type_overlaps)
    decodes the wire blobs and computes the same set; the Python body stays
    untouched and runs when the gate is off or the seam defers.

    Each test compares the pure-Python result (gate off) with the seam
    result (gate on) and asserts they are identical.
    """

    def setUp(self) -> None:
        from mypy.messages import _set_native_messages_active

        self.fx = TypeFixture()
        self._set_active = _set_native_messages_active
        self._set_active(True)
        self._buf = _WriteBuffer()

    def tearDown(self) -> None:
        self._set_active(False)

    def _bytes_of(self, t: Type) -> bytes:
        self._buf = _WriteBuffer()
        t.write(self._buf)
        return self._buf.getvalue()

    def _dup_a(self) -> Instance:
        # A realistic TypeInfo for class A in module other: defn.name "A"
        # (short name), fullname "other.A". make_type_info("other.A") cannot
        # produce this shape, so build the TypeInfo directly.
        from mypy.nodes import Block, ClassDef, SymbolTable, TypeInfo

        class_def = ClassDef("A", Block([]), None, [])
        class_def.fullname = "other.A"
        info = TypeInfo(SymbolTable(), class_def, "other")
        info.mro = [info]
        info.bases = []
        return Instance(info, [])

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def assert_overlap_par(self, *types: Type) -> None:
        from mypy.messages import find_type_overlaps

        off = self._with_gate(False, lambda: find_type_overlaps(*types))
        on = self._with_gate(True, lambda: find_type_overlaps(*types))
        assert_equal(on, off, f"find_type_overlaps parity {types}")
        assert_equal(set(on), set(off), f"find_type_overlaps set parity {types}")

    def _assert_engages(self, *types: Type) -> None:
        result = _type_kernel.rust_find_type_overlaps(
            [self._bytes_of(t) for t in types]
        )
        assert result is not None, f"rust find_type_overlaps did not engage for {types}"

    def test_overlapping_pair(self) -> None:
        # Two classes with the same short name in different modules.
        self.assert_overlap_par(self.fx.a, self._dup_a())
        self._assert_engages(self.fx.a, self._dup_a())

    def test_disjoint_pair(self) -> None:
        # Different short names, no overlap.
        self.assert_overlap_par(self.fx.a, self.fx.b)

    def test_three_types_one_overlap(self) -> None:
        # A collides with another A; C is disjoint; only A fullnames return.
        self.assert_overlap_par(self.fx.a, self._dup_a(), self.fx.c)
        self._assert_engages(self.fx.a, self._dup_a(), self.fx.c)

    def test_no_overlap(self) -> None:
        # Three disjoint names: empty set.
        self.assert_overlap_par(self.fx.a, self.fx.b, self.fx.c)

    def test_typing_injection(self) -> None:
        # `List` also in TYPES_FOR_UNIMPORTED_HINTS: typing.List is injected
        # into the short-name group when a user List collides.
        from mypy.nodes import Block, ClassDef, SymbolTable, TypeInfo

        class_def = ClassDef("List", Block([]), None, [])
        class_def.fullname = "m.List"
        info = TypeInfo(SymbolTable(), class_def, "m")
        info.mro = [info]
        info.bases = []
        lst2 = Instance(info, [])
        self.assert_overlap_par(lst2, lst2)
        self._assert_engages(lst2)

    def test_typevar_scoped_name(self) -> None:
        # Same short TypeVar name, different namespaces: both scoped names
        # are returned.
        id1 = TypeVarId(1, namespace="mod1")
        id2 = TypeVarId(2, namespace="mod2")
        tv1 = TypeVarType("T", "T", id1, [], self.fx.o, self.fx.o)
        tv2 = TypeVarType("T", "T", id2, [], self.fx.o, self.fx.o)
        self.assert_overlap_par(tv1, tv2)
        self._assert_engages(tv1, tv2)

    def test_union_inner_overlap(self) -> None:
        # Overlap nested inside a union arg is detected.
        u = UnionType.make_union([self.fx.a, self._dup_a()])
        self.assert_overlap_par(u)
        self._assert_engages(u)

    def test_alias_defers_to_python(self) -> None:
        # TypeAliasType: the wire carries no alias node, so the Rust seam
        # defers and the pure-Python body runs (gate-on == gate-off).
        from mypy.messages import find_type_overlaps
        from mypy.nodes import TypeAlias

        alias = TypeAlias(self.fx.a, "mod.TA", "mod", -1, -1)
        alias_type = TypeAliasType(alias, [])
        # The seam must decline (None) on the alias wire form.
        assert _type_kernel.rust_find_type_overlaps(
            [self._bytes_of(alias_type)]
        ) is None, "rust should defer on TypeAliasType"
        off = self._with_gate(False, lambda: find_type_overlaps(alias_type))
        on = self._with_gate(True, lambda: find_type_overlaps(alias_type))
        assert_equal(on, off, "alias find_type_overlaps parity")
@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCheckPatternSuite(Suite):
    """Parity tests for the M22 checkpattern Rust helpers.

    Each test serializes a Type via Type.write(WriteBuffer) and asserts
    that the Rust helper agrees with the Python implementation. The suite
    mirrors the standalone functions in mypy/checkpattern.py:

    * rust_is_uninhabited vs isinstance(get_proper_type(t), UninhabitedType)
    * rust_get_match_arg_names vs the Python get_match_arg_names
    * rust_get_type_range vs the Python get_type_range bool-LKV unwrap logic
    """

    def setUp(self) -> None:
        self.fx = TypeFixture()
        self._buf = _WriteBuffer()
        self._resolver = self._build_resolver(self._type_infos(), [])

    def _type_infos(self) -> list[TypeInfo]:

        infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                infos.append(value)
        return infos

    def _build_resolver(self, infos: list[TypeInfo], aliases: list[Any]) -> Any:
        return _type_kernel.build_native_resolver(infos, aliases)

    def _bytes_of(self, t: Type) -> bytes:
        self._buf = _WriteBuffer()
        t.write(self._buf)
        return self._buf.getvalue()

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        from mypy.checkpattern import _set_native_checkpattern_active

        _set_native_checkpattern_active(active)
        try:
            return fn()
        finally:
            _set_native_checkpattern_active(True)

    def test_is_uninhabited_true(self) -> None:
        t = UninhabitedType()
        assert _type_kernel.rust_is_uninhabited(self._bytes_of(t), self._resolver) is True

    def test_is_uninhabited_false(self) -> None:
        t = self.fx.a
        assert _type_kernel.rust_is_uninhabited(self._bytes_of(t), self._resolver) is False

    def test_is_uninhabited_none_type(self) -> None:
        t = NoneType()
        assert _type_kernel.rust_is_uninhabited(self._bytes_of(t), self._resolver) is False

    def test_is_uninhabited_union_with_uninhabited(self) -> None:
        # Union containing UninhabitedType: get_proper_type keeps it in the
        # union, but is_uninhabited checks the whole type, not items.
        t = UnionType.make_union([self.fx.a, UninhabitedType()])
        assert _type_kernel.rust_is_uninhabited(self._bytes_of(t), self._resolver) is False

    def test_is_uninhabited_alias_to_uninhabited(self) -> None:
        # A TypeAliasType resolving to UninhabitedType must answer True
        # (Python: isinstance(get_proper_type(typ), UninhabitedType)); the
        # Rust seam expands the alias via the resolver snapshot.
        from mypy.checkpattern import is_uninhabited
        from mypy.nodes import TypeAlias

        alias = TypeAlias(UninhabitedType(), "mod.Never", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        resolver = self._build_resolver([], [alias])
        assert _type_kernel.rust_is_uninhabited(self._bytes_of(typ), resolver) is True
        off = self._with_gate(False, lambda: is_uninhabited(typ))
        on = self._with_gate(True, lambda: is_uninhabited(typ))
        assert_equal(on, off, "alias-to-uninhabited is_uninhabited parity")

    def test_is_uninhabited_alias_to_non_uninhabited(self) -> None:
        from mypy.checkpattern import is_uninhabited
        from mypy.nodes import TypeAlias

        alias = TypeAlias(self.fx.a, "mod.A", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        resolver = self._build_resolver([], [alias])
        assert _type_kernel.rust_is_uninhabited(self._bytes_of(typ), resolver) is False
        assert_equal(
            self._with_gate(True, lambda: is_uninhabited(typ)),
            self._with_gate(False, lambda: is_uninhabited(typ)),
            "alias-to-instance is_uninhabited parity",
        )

    def test_is_uninhabited_alias_missing_snapshot(self) -> None:
        # Missing resolver snapshot: Rust defers (None) and Python falls back.
        from mypy.checkpattern import is_uninhabited
        from mypy.nodes import TypeAlias

        alias = TypeAlias(UninhabitedType(), "mod.Missing", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        off = self._with_gate(False, lambda: is_uninhabited(typ))
        on = self._with_gate(True, lambda: is_uninhabited(typ))
        assert_equal(on, off, "missing-snapshot is_uninhabited parity")
        assert on is True

    def test_get_match_arg_names_all_str(self) -> None:
        # TupleType with str-literal items -> list of str values.
        t = TupleType([self.fx.lit_str1, self.fx.lit_str2], self.fx.std_tuple)
        result = _type_kernel.rust_get_match_arg_names(self._bytes_of(t), self._resolver)
        assert result == ["x", "y"]

    def test_get_match_arg_names_mixed(self) -> None:
        # TupleType with a non-str-literal item -> None in that position.
        t = TupleType([self.fx.lit_str1, self.fx.a], self.fx.std_tuple)
        result = _type_kernel.rust_get_match_arg_names(self._bytes_of(t), self._resolver)
        assert result == ["x", None]

    def test_get_match_arg_names_no_literals(self) -> None:
        t = TupleType([self.fx.a, self.fx.b], self.fx.std_tuple)
        result = _type_kernel.rust_get_match_arg_names(self._bytes_of(t), self._resolver)
        assert result == [None, None]

    def test_get_match_arg_names_empty(self) -> None:
        t = TupleType([], self.fx.std_tuple)
        result = _type_kernel.rust_get_match_arg_names(self._bytes_of(t), self._resolver)
        assert result == []

    def test_get_match_arg_names_alias_item(self) -> None:
        # An item that is a str-alias expands through the resolver to its
        # Literal[str], matching try_getting_str_literals_from_type.
        from mypy.nodes import TypeAlias

        alias = TypeAlias(self.fx.lit_str1, "mod.S", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        t = TupleType([typ, self.fx.lit_str2], self.fx.std_tuple)
        resolver = self._build_resolver([], [alias])
        assert _type_kernel.rust_get_match_arg_names(self._bytes_of(t), resolver) == [
            "x",
            "y",
        ]

    def test_get_match_arg_names_alias_missing_snapshot_defers(self) -> None:
        # An unresolvable alias item: Rust defers (None) so Python resolves it.
        from mypy.checkpattern import get_match_arg_names
        from mypy.nodes import TypeAlias

        alias = TypeAlias(self.fx.lit_str1, "mod.Missing", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        t = TupleType([typ, self.fx.lit_str2], self.fx.std_tuple)
        off = self._with_gate(False, lambda: get_match_arg_names(t))
        on = self._with_gate(True, lambda: get_match_arg_names(t))
        assert_equal(on, off, "missing-snapshot match-arg parity")
        assert on == ["x", "y"]

    def test_get_type_range_bool_lkv(self) -> None:
        # Instance with a bool last_known_value should return True (unwrap).
        t = Instance(self.fx.bool_type_info, [], last_known_value=self.fx.lit_true)
        assert _type_kernel.rust_get_type_range(self._bytes_of(t)) is True

    def test_get_type_range_bool_lkv_false(self) -> None:
        t = Instance(self.fx.bool_type_info, [], last_known_value=self.fx.lit_false)
        assert _type_kernel.rust_get_type_range(self._bytes_of(t)) is True

    def test_get_type_range_int_lkv(self) -> None:
        # Instance with an int last_known_value should return False (no unwrap).
        t = self.fx.lit1_inst
        assert _type_kernel.rust_get_type_range(self._bytes_of(t)) is False

    def test_get_type_range_no_lkv(self) -> None:
        t = self.fx.a
        assert _type_kernel.rust_get_type_range(self._bytes_of(t)) is False

    def test_get_type_range_none_type(self) -> None:
        t = NoneType()
        assert _type_kernel.rust_get_type_range(self._bytes_of(t)) is False

    def test_get_type_range_str_lkv(self) -> None:
        # Instance with a str last_known_value should return False (not bool).
        t = self.fx.lit_str1_inst
        assert _type_kernel.rust_get_type_range(self._bytes_of(t)) is False

    def test_should_self_match_int(self) -> None:
        # int is in self_match_type_names, so should_self_match(int) = True.
        from type_kernel import build_native_resolver

        int_info = self.fx.make_type_info("builtins.int")
        resolver = build_native_resolver([int_info, self.fx.oi], [])
        int_type = Instance(int_info, [])
        self_match_union = UnionType.make_union([int_type])
        result = _type_kernel.rust_should_self_match(
            self._bytes_of(int_type),
            False,  # has_match_args
            self._bytes_of(self_match_union),
            resolver,
        )
        assert result is True

    def test_should_self_match_custom_class(self) -> None:
        # A custom class not in self_match_type_names -> False.
        from type_kernel import build_native_resolver

        resolver = build_native_resolver([self.fx.ai, self.fx.oi], [])
        int_info = self.fx.make_type_info("builtins.int")
        int_type = Instance(int_info, [])
        self_match_union = UnionType.make_union([int_type])
        result = _type_kernel.rust_should_self_match(
            self._bytes_of(self.fx.a),
            False,
            self._bytes_of(self_match_union),
            resolver,
        )
        assert result is False

    def test_should_self_match_any(self) -> None:
        # AnyType -> always False.
        from type_kernel import build_native_resolver

        int_info = self.fx.make_type_info("builtins.int")
        resolver = build_native_resolver([int_info, self.fx.oi], [])
        int_type = Instance(int_info, [])
        self_match_union = UnionType.make_union([int_type])
        any_t = AnyType(TypeOfAny.special_form)
        result = _type_kernel.rust_should_self_match(
            self._bytes_of(any_t),
            False,
            self._bytes_of(self_match_union),
            resolver,
        )
        assert result is False

    def test_can_match_sequence_object(self) -> None:
        # object is more general than Sequence: is_subtype(Sequence, object)
        # is True, so can_match_sequence(object) = True.
        from type_kernel import build_native_resolver

        seq_info = self.fx.make_type_info("typing.Sequence", mro=[self.fx.oi])
        str_info = self.fx.make_type_info("builtins.str")
        resolver = build_native_resolver(
            [seq_info, str_info, self.fx.oi], []
        )
        non_seq_union = UnionType.make_union([Instance(str_info, [])])
        seq_type = Instance(seq_info, [self.fx.a])
        # object: is_subtype(str, object) is False (non_seq check passes),
        # then is_subtype(object, Sequence) is False, but
        # is_subtype(Sequence, object) is True -> can_match = True.
        result = _type_kernel.rust_can_match_sequence(
            self._bytes_of(self.fx.o),
            self._bytes_of(non_seq_union),
            self._bytes_of(seq_type),
            resolver,
        )
        # Rust may defer (None) on generic subtype checks; when it does,
        # the Python fallback handles it. Assert True when it decides.
        assert result is None or result is True

    def test_can_match_sequence_str(self) -> None:
        # str is in non_sequence_match_types -> False.
        from type_kernel import build_native_resolver

        str_info = self.fx.make_type_info("builtins.str")
        seq_info = self.fx.make_type_info("typing.Sequence", mro=[self.fx.oi])
        resolver = build_native_resolver([str_info, seq_info, self.fx.oi], [])
        str_type = Instance(str_info, [])
        non_seq_union = UnionType.make_union([str_type])
        seq_type = Instance(seq_info, [self.fx.a])
        result = _type_kernel.rust_can_match_sequence(
            self._bytes_of(str_type),
            self._bytes_of(non_seq_union),
            self._bytes_of(seq_type),
            resolver,
        )
        assert result is False

    def test_can_match_sequence_any(self) -> None:
        # AnyType -> always True.
        from type_kernel import build_native_resolver

        str_info = self.fx.make_type_info("builtins.str")
        seq_info = self.fx.make_type_info("typing.Sequence", mro=[self.fx.oi])
        resolver = build_native_resolver([str_info, seq_info, self.fx.oi], [])
        any_t = AnyType(TypeOfAny.special_form)
        non_seq_union = UnionType.make_union([Instance(str_info, [])])
        seq_type = Instance(seq_info, [self.fx.a])
        result = _type_kernel.rust_can_match_sequence(
            self._bytes_of(any_t),
            self._bytes_of(non_seq_union),
            self._bytes_of(seq_type),
            resolver,
        )
        assert result is True


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCheckCallSuite(Suite):
    """Parity suite for M25: check_call decision helpers ported to Rust.

    Tests `rust_real_union` and `rust_possible_none_type_var_overlap`
    against the pure-Python implementations in `mypy.checkexpr`. Each
    test toggles the native gate off/on and compares.

    Since issue #873 the two seams expand top-level TypeAliasType operands
    through the alias resolver (mirroring `get_proper_type` /
    `get_proper_types`); a resolver is built per test so alias parity is
    exercised too.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active
        from mypy.state import state as _state

        self.fx = TypeFixture()
        self._set_active = _set_native_checkexpr_active
        self._set_active(True)
        self._state = _state
        self.resolver = _type_kernel.build_native_resolver(self._collect_type_infos(), [])

    def tearDown(self) -> None:
        self._set_active(False)

    def _collect_type_infos(self) -> list[TypeInfo]:
        infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                infos.append(value)
        return infos

    def _rebuild_resolver(self, aliases: list[Any]) -> None:
        self.resolver = _type_kernel.build_native_resolver(self._collect_type_infos(), aliases)

    def _make_alias(self, fullname: str, target: Type) -> Any:  # TypeAlias
        from mypy.nodes import TypeAlias

        return TypeAlias(target, fullname, "mod", -1, -1, alias_tvars=[])

    def _alias_type(self, alias: Any) -> Any:  # TypeAliasType
        return TypeAliasType(alias, [])

    def _serialize(self, t: Type) -> bytes:
        from mypy.checkexpr import _serialize_type_for_checkexpr

        return _serialize_type_for_checkexpr(t)

    def _rust_real_union(self, t: Type, strict_optional: bool) -> bool | None:
        import type_kernel as tk

        return tk.rust_real_union(self.resolver, self._serialize(t), strict_optional)

    def _rust_overlap(
        self, arg_types: list[Type], targets: list[CallableType] | list[Type]
    ) -> bool | None:
        import type_kernel as tk

        return tk.rust_possible_none_type_var_overlap(
            self.resolver,
            [self._serialize(t) for t in arg_types],
            [self._serialize(t) for t in targets],
        )

    def _py_real_union(self, t: Type, strict_optional: bool) -> bool:
        old = self._state.strict_optional
        self._state.strict_optional = strict_optional
        try:
            p = get_proper_type(t)
            return isinstance(p, UnionType) and len(p.relevant_items()) > 1
        finally:
            self._state.strict_optional = old

    def _py_overlap(self, arg_types: list[Type], targets: list[CallableType]) -> bool:
        """Pure-Python mirror of `possible_none_type_var_overlap`."""
        if not targets or not arg_types:
            return False
        has_optional_arg = False
        for arg_type in get_proper_types(arg_types):
            if not isinstance(arg_type, UnionType):
                continue
            for item in get_proper_types(arg_type.items):
                if isinstance(item, NoneType):
                    has_optional_arg = True
                    break
            if has_optional_arg:
                break
        if not has_optional_arg:
            return False
        min_prefix = min(len(c.arg_types) for c in targets)
        for i in range(min_prefix):
            has_none = any(
                isinstance(get_proper_type(c.arg_types[i]), NoneType) for c in targets
            )
            has_typevar = any(
                isinstance(get_proper_type(c.arg_types[i]), TypeVarType) for c in targets
            )
            if has_none and has_typevar:
                return True
        return False

    # --- real_union ---

    def test_real_union_non_union(self) -> None:
        for t in [self.fx.a, self.fx.anyt, self.fx.nonet, self.fx.t]:
            assert self._rust_real_union(t, True) == self._py_real_union(t, True)

    def test_real_union_single_item_union(self) -> None:
        t = UnionType.make_union([self.fx.a])
        assert self._rust_real_union(t, True) == self._py_real_union(t, True)

    def test_real_union_multi_item_union(self) -> None:
        t = UnionType.make_union([self.fx.a, self.fx.b])
        assert self._rust_real_union(t, True) == self._py_real_union(t, True)

    def test_real_union_strict_optional_keeps_none(self) -> None:
        t = UnionType.make_union([self.fx.a, NoneType()])
        assert self._rust_real_union(t, True) == self._py_real_union(t, True)
        assert self._rust_real_union(t, True) is True

    def test_real_union_non_strict_strips_none(self) -> None:
        t = UnionType.make_union([self.fx.a, NoneType()])
        assert self._rust_real_union(t, False) == self._py_real_union(t, False)
        assert self._rust_real_union(t, False) is False

    def test_real_union_non_strict_multi_without_none(self) -> None:
        t = UnionType.make_union([self.fx.a, self.fx.b])
        assert self._rust_real_union(t, False) == self._py_real_union(t, False)
        assert self._rust_real_union(t, False) is True

    def test_real_union_non_strict_strips_all_none(self) -> None:
        t = UnionType.make_union([NoneType(), NoneType()])
        assert self._rust_real_union(t, False) == self._py_real_union(t, False)

    def test_real_union_nested_union(self) -> None:
        inner = UnionType.make_union([self.fx.a, NoneType()])
        outer = UnionType.make_union([inner, self.fx.b])
        assert self._rust_real_union(outer, True) == self._py_real_union(outer, True)

    # --- possible_none_type_var_overlap ---

    def _callable(self, arg_types: list[Type], variables: list[Type] | None = None) -> CallableType:
        return CallableType(
            arg_types,
            [ARG_POS] * len(arg_types),
            [None] * len(arg_types),
            self.fx.anyt,
            self.fx.function,
            variables=variables or [],  # type: ignore[arg-type]
        )

    def test_overlap_empty_args(self) -> None:
        targets = [self._callable([self.fx.a])]
        assert self._rust_overlap([], targets) is False

    def test_overlap_empty_targets(self) -> None:
        assert self._rust_overlap([self.fx.a], []) is False

    def test_overlap_no_union_arg(self) -> None:
        targets = [self._callable([NoneType(), self.fx.t])]
        assert self._rust_overlap([self.fx.a], targets) is False

    def test_overlap_union_without_none(self) -> None:
        arg = UnionType.make_union([self.fx.a, self.fx.b])
        targets = [self._callable([NoneType(), self.fx.t])]
        assert self._rust_overlap([arg], targets) is False

    def test_overlap_union_with_none_no_typevar(self) -> None:
        arg = UnionType.make_union([self.fx.a, NoneType()])
        targets = [self._callable([NoneType(), self.fx.a])]
        assert self._rust_overlap([arg], targets) is False

    def test_overlap_union_with_none_and_typevar_same_pos(self) -> None:
        arg = UnionType.make_union([self.fx.a, NoneType()])
        target1 = self._callable([NoneType()])
        target2 = self._callable([self.fx.t])
        assert self._rust_overlap([arg], [target1, target2]) is True

    def test_overlap_single_target_none_and_typevar_different_pos(self) -> None:
        # NoneType at pos 0, TypeVar at pos 1: neither position has both.
        arg = UnionType.make_union([self.fx.a, NoneType()])
        target = self._callable([NoneType(), self.fx.t])
        assert self._rust_overlap([arg], [target]) is False

    def test_overlap_typevar_different_position(self) -> None:
        arg = UnionType.make_union([self.fx.a, NoneType()])
        target1 = self._callable([NoneType(), self.fx.a])
        target2 = self._callable([self.fx.a, self.fx.t])
        assert self._rust_overlap([arg], [target1, target2]) is False

    def test_overlap_multiple_positions_only_first_matches(self) -> None:
        arg = UnionType.make_union([self.fx.a, NoneType()])
        target1 = self._callable([NoneType(), self.fx.a, self.fx.a])
        target2 = self._callable([self.fx.t, self.fx.a, self.fx.a])
        assert self._rust_overlap([arg], [target1, target2]) is True

    def test_overlap_none_in_second_position(self) -> None:
        arg = UnionType.make_union([self.fx.a, NoneType()])
        target1 = self._callable([self.fx.a, NoneType()])
        target2 = self._callable([self.fx.a, self.fx.t])
        assert self._rust_overlap([arg], [target1, target2]) is True

    def test_overlap_min_prefix_limits_search(self) -> None:
        arg = UnionType.make_union([self.fx.a, NoneType()])
        # target1 has 1 arg (NoneType), target2 has 3 (a, a, t).
        # min_prefix = 1, position 0: none vs a -> no match.
        target1 = self._callable([NoneType()])
        target2 = self._callable([self.fx.a, self.fx.a, self.fx.t])
        assert self._rust_overlap([arg], [target1, target2]) is False

    # --- real_union / overlap with TypeAliasType operands (#873) ---

    def test_real_union_alias_to_union_parity(self) -> None:
        # T = Union[A, B]: the alias expands and both Rust and Python count
        # the two union items -> True (strict_optional).
        alias = self._make_alias("mod.T", UnionType.make_union([self.fx.a, self.fx.b]))
        self._rebuild_resolver([alias])
        alias_t = self._alias_type(alias)
        assert self._rust_real_union(alias_t, True) == self._py_real_union(alias_t, True)
        assert self._rust_real_union(alias_t, True) is True

    def test_real_union_alias_to_non_union_parity(self) -> None:
        # T = A (non-union): after expansion both report False.
        alias = self._make_alias("mod.T", self.fx.a)
        self._rebuild_resolver([alias])
        alias_t = self._alias_type(alias)
        assert self._rust_real_union(alias_t, True) == self._py_real_union(alias_t, True)
        assert self._rust_real_union(alias_t, True) is False

    def test_overlap_alias_arg_parity(self) -> None:
        # T = Union[A, None]; overlap(T, [None], [Tvar]) finds Both.
        alias = self._make_alias("mod.T", UnionType.make_union([self.fx.a, NoneType()]))
        self._rebuild_resolver([alias])
        arg = self._alias_type(alias)
        target1 = self._callable([NoneType()])
        target2 = self._callable([self.fx.t])
        rust = self._rust_overlap([arg], [target1, target2])
        py = self._py_overlap([arg], [target1, target2])
        assert rust == py
        assert rust is True

    def test_overlap_alias_formal_parity(self) -> None:
        # A formal typed as an alias to NoneType + another as a TypeVar:
        # both Rust and Python resolve the formal and find the overlap.
        alias_none = self._make_alias("mod.N", NoneType())
        self._rebuild_resolver([alias_none])
        arg = UnionType.make_union([self.fx.a, NoneType()])
        target1 = self._callable([self._alias_type(alias_none)])
        target2 = self._callable([self.fx.t])
        rust = self._rust_overlap([arg], [target1, target2])
        py = self._py_overlap([arg], [target1, target2])
        assert rust == py
        assert rust is True


@skipUnless(
    _NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext"
)
class NativeServerDepsSuite(Suite):
    """Parity tests for the Rust `get_type_triggers` port (M28).

    Each test calls `get_type_triggers` with the Rust gate on and off and
    asserts the trigger lists match. The Rust path walks live Python `Type`
    objects via PyO3 and returns `None` for unsupported cases; when it
    returns `None`, the Python `TypeTriggersVisitor` runs instead, so parity
    holds by construction. These tests verify the Rust path actually handles
    the case (does not defer) and produces the same trigger list.
    """

    def setUp(self) -> None:
        from mypy.server.deps import _set_native_server_deps_active
        from mypy.server.trigger import make_trigger, make_wildcard_trigger

        self.fx = TypeFixture()
        self._set_active = _set_native_server_deps_active
        self.make_trigger = make_trigger
        self.make_wildcard_trigger = make_wildcard_trigger

    def _triggers(self, typ: Type, use_logical: bool = False) -> list[str]:
        from mypy.server.deps import get_type_triggers

        self._set_active(False)
        py = get_type_triggers(typ, use_logical)
        self._set_active(True)
        rs = get_type_triggers(typ, use_logical)
        assert_equal(
            rs,
            py,
            f"Rust/Python mismatch for {typ!r} (logical={use_logical})",
        )
        return rs

    def test_instance_simple(self) -> None:
        triggers = self._triggers(self.fx.a)
        assert_equal(triggers, [self.make_trigger("A")])

    def test_instance_generic(self) -> None:
        triggers = self._triggers(self.fx.ga)
        assert_equal(triggers, [self.make_trigger("G"), self.make_trigger("A")])

    def test_none_type(self) -> None:
        triggers = self._triggers(self.fx.nonet)
        assert_equal(triggers, [])

    def test_any_type(self) -> None:
        triggers = self._triggers(self.fx.anyt)
        assert_equal(triggers, [])

    def test_any_with_missing_import(self) -> None:
        any_t = AnyType(
            TypeOfAny.from_unimported_type, missing_import_name="missing_mod"
        )
        triggers = self._triggers(any_t)
        assert_equal(triggers, [self.make_trigger("missing_mod")])

    def test_uninhabited_type(self) -> None:
        triggers = self._triggers(self.fx.uninhabited)
        assert_equal(triggers, [])

    def test_literal_type(self) -> None:
        triggers = self._triggers(self.fx.lit1)
        assert_equal(triggers, [self.make_trigger("A")])

    def test_tuple_type(self) -> None:
        t = TupleType([self.fx.a, self.fx.b], self.fx.std_tuple)
        triggers = self._triggers(t)
        assert_equal(
            triggers,
            [
                self.make_trigger("A"),
                self.make_trigger("B"),
                self.make_trigger("builtins.tuple"),
            ],
        )

    def test_union_type(self) -> None:
        u = UnionType([self.fx.a, self.fx.b])
        triggers = self._triggers(u)
        assert_equal(triggers, [self.make_trigger("A"), self.make_trigger("B")])

    def test_type_var(self) -> None:
        triggers = self._triggers(self.fx.t)
        # The fixture TypeVar has fullname "T" set, plus upper_bound (object).
        assert_equal(
            triggers,
            [self.make_trigger("T"), self.make_trigger("builtins.object")],
        )

    def test_type_type_no_logical(self) -> None:
        triggers = self._triggers(self.fx.type_a, use_logical=False)
        # Without logical deps, TypeType appends __init__ and __new__ triggers
        # AFTER the item triggers (matching Python's ordering).
        assert_equal(
            triggers,
            [
                self.make_trigger("A"),
                self.make_trigger("A.__init__"),
                self.make_trigger("A.__new__"),
            ],
        )

    def test_type_type_logical(self) -> None:
        triggers = self._triggers(self.fx.type_a, use_logical=True)
        # With logical deps, no __init__/__new__ appended.
        assert_equal(triggers, [self.make_trigger("A")])

    def test_instance_with_last_known_value(self) -> None:
        triggers = self._triggers(self.fx.lit1_inst)
        assert_equal(triggers, [self.make_trigger("A"), self.make_trigger("A")])

    def test_callable_type(self) -> None:
        c = CallableType(
            [self.fx.a, self.fx.b],
            [ARG_POS, ARG_POS],
            [None, None],
            self.fx.anyt,
            self.fx.function,
        )
        triggers = self._triggers(c)
        # Fallback (builtins.function) is processed separately by Python.
        assert_equal(triggers, [self.make_trigger("A"), self.make_trigger("B")])

    def test_overloaded(self) -> None:
        c1 = CallableType(
            [self.fx.a], [ARG_POS], [None], self.fx.anyt, self.fx.function
        )
        c2 = CallableType(
            [self.fx.b], [ARG_POS], [None], self.fx.anyt, self.fx.function
        )
        ov = Overloaded([c1, c2])
        triggers = self._triggers(ov)
        assert_equal(triggers, [self.make_trigger("A"), self.make_trigger("B")])


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCheckMemberSuite(Suite):
    """Parity tests for the M20 checkmember Rust port.

    Verifies that `rust_bind_self_fast` agrees with the Python
    `bind_self_fast` for CallableType and Overloaded, including the
    keep-unchanged semantics for *args/**kwargs and empty-arg callables,
    and the deferral (None return) for non-callable types. Also verifies
    `rust_instance_fallback`, `rust_has_operator`, `rust_meta_has_operator`,
    and `rust_defined_in_superclass` against the Python originals.
    """

    def setUp(self) -> None:
        import type_kernel as _tk
        from librt.internal import WriteBuffer as _WB

        from mypy.checkmember import (
            _set_native_checkmember_active,
            _set_native_checkmember_resolver,
        )
        from mypy.wirefixup import set_wire_typeinfo_map

        self._tk = _tk
        self._WB = _WB
        self._set_active = _set_native_checkmember_active
        self._set_resolver = _set_native_checkmember_resolver
        self.fx = TypeFixture()
        # Production class typevars bind TypeVarId(raw_id, namespace=<class
        # fullname>) (types.py:554). Mirror that here so fixture tvars
        # match the Rust expand env keyed on the instance type_ref.
        for info in (self.fx.gi, self.fx.g2i, self.fx.hi):
            for tv in info.defn.type_vars:
                tv.id = TypeVarId(tv.id.raw_id, namespace=info.fullname)
        type_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.ci,
            self.fx.di,
            self.fx.ei,
            self.fx.e2i,
            self.fx.e3i,
            self.fx.fi,
            self.fx.f2i,
            self.fx.f3i,
            self.fx.gi,
            self.fx.g2i,
            self.fx.hi,
            self.fx.std_tuplei,
            self.fx.type_typei,
            self.fx.bool_type_info,
            self.fx.str_type_info,
            self.fx.functioni,
        ]
        self.resolver = _tk.build_native_resolver(type_infos, [])
        self._set_resolver(self.resolver)
        set_wire_typeinfo_map({info.fullname: info for info in type_infos})
        self._set_active(True)

    def tearDown(self) -> None:
        from mypy.wirefixup import set_wire_typeinfo_map

        set_wire_typeinfo_map(None)
        self._set_resolver(None)
        self._set_active(False)

    def _bytes_of(self, t: Type) -> bytes:
        buf = self._WB()
        t.write(buf)
        return buf.getvalue()

    def _make_callable(self, arg_kinds: list[ArgKind], ret: Type | None = None) -> CallableType:

        return CallableType(
            arg_types=[self.fx.o],
            arg_kinds=arg_kinds,
            arg_names=["self"],
            ret_type=ret or self.fx.o,
            fallback=self.fx.function,
            is_bound=False,
        )

    def test_bind_self_fast_plain_callable(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_POS

        method = self._make_callable([ARG_POS])
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert result.is_bound is True
        assert len(result.arg_types) == 0
        assert len(result.arg_kinds) == 0
        assert len(result.arg_names) == 0

    def test_bind_self_fast_preserves_ret_type(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_POS

        method = self._make_callable([ARG_POS], ret=self.fx.a)
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert result.ret_type == self.fx.a

    def test_bind_self_fast_preserves_variables(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_POS

        method = CallableType(
            arg_types=[self.fx.o],
            arg_kinds=[ARG_POS],
            arg_names=["self"],
            ret_type=self.fx.t,
            fallback=self.fx.function,
            variables=[self.fx.t],
            is_bound=False,
        )
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert len(result.variables) == 1

    def test_bind_self_fast_overloaded(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_POS

        item1 = self._make_callable([ARG_POS])
        item2 = self._make_callable([ARG_POS])
        overloaded = Overloaded([item1, item2])
        result = bind_self_fast(overloaded)
        assert isinstance(result, Overloaded)
        assert len(result.items) == 2
        for item in result.items:
            assert item.is_bound is True

    def test_bind_self_fast_defers_star_args(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_STAR

        method = self._make_callable([ARG_STAR])
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert result.is_bound is False
        assert len(result.arg_types) == 1

    def test_bind_self_fast_defers_star2(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_STAR2

        method = self._make_callable([ARG_STAR2])
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert result.is_bound is False
        assert len(result.arg_types) == 1

    def test_bind_self_fast_rust_round_trip_plain_callable(self) -> None:
        # New semantics: plain callable comes back bound through the wire.
        from mypy.checkmember import _deserialize_type_for_checkmember
        from mypy.nodes import ARG_POS

        method = self._make_callable([ARG_POS])
        rust_bytes = self._tk.rust_bind_self_fast(self._bytes_of(method))
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(bytes(rust_bytes))
        assert isinstance(decoded, CallableType)
        assert decoded.is_bound is True
        assert len(decoded.arg_types) == 0

    def test_bind_self_fast_rust_keeps_star_unchanged(self) -> None:
        # *args / **kwargs return the method unchanged (matches Python).
        from mypy.checkmember import _deserialize_type_for_checkmember
        from mypy.nodes import ARG_STAR

        method = self._make_callable([ARG_STAR])
        rust_bytes = self._tk.rust_bind_self_fast(self._bytes_of(method))
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(bytes(rust_bytes))
        assert isinstance(decoded, CallableType)
        assert decoded.is_bound is False
        assert len(decoded.arg_types) == 1

    def test_bind_self_fast_rust_returns_none_for_non_callable(self) -> None:
        rust_bytes = self._tk.rust_bind_self_fast(self._bytes_of(self.fx.a))
        assert rust_bytes is None

    def test_classify_member_access_instance(self) -> None:
        # Instance -> MA_INSTANCE (0).
        code = self._tk.rust_classify_member_access(
            self.resolver, self._bytes_of(self.fx.a)
        )
        assert code == 0

    def test_classify_member_access_none(self) -> None:
        code = self._tk.rust_classify_member_access(
            self.resolver, self._bytes_of(NoneType())
        )
        assert code == 8

    def test_classify_member_access_union(self) -> None:
        u = UnionType([self.fx.a, self.fx.b])
        code = self._tk.rust_classify_member_access(
            self.resolver, self._bytes_of(u)
        )
        assert code == 2

    def test_classify_member_access_type_type(self) -> None:
        tt = TypeType(self.fx.a)
        code = self._tk.rust_classify_member_access(
            self.resolver, self._bytes_of(tt)
        )
        assert code == 4

    def test_classify_member_access_deleted(self) -> None:
        from mypy.types import DeletedType

        dt = DeletedType("x")
        code = self._tk.rust_classify_member_access(
            self.resolver, self._bytes_of(dt)
        )
        assert code == 10

    def test_classify_member_access_uninhabited(self) -> None:
        ui = UninhabitedType()
        code = self._tk.rust_classify_member_access(
            self.resolver, self._bytes_of(ui)
        )
        assert code == 11

    def test_bind_self_fast_preserves_name(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_POS

        method = CallableType(
            arg_types=[self.fx.o],
            arg_kinds=[ARG_POS],
            arg_names=["self"],
            ret_type=self.fx.o,
            fallback=self.fx.function,
            name="my_method",
            is_bound=False,
        )
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert result.name == "my_method"

    def test_bind_self_fast_round_trip_multiple_args(self) -> None:
        from mypy.checkmember import bind_self_fast
        from mypy.nodes import ARG_POS

        method = CallableType(
            arg_types=[self.fx.o, self.fx.a, self.fx.b],
            arg_kinds=[ARG_POS, ARG_POS, ARG_POS],
            arg_names=["self", "x", "y"],
            ret_type=self.fx.a,
            fallback=self.fx.function,
            is_bound=False,
        )
        result = bind_self_fast(method)
        assert isinstance(result, CallableType)
        assert result.is_bound is True
        assert len(result.arg_types) == 2
        assert result.arg_names == ["x", "y"]

    def test_has_operator_parity_present(self) -> None:
        from mypy.checkmember import has_operator

        self._set_active(False)
        try:
            expected = has_operator(self.fx.a, "__bool__")
        finally:
            self._set_active(True)
        actual = has_operator(self.fx.a, "__bool__")
        assert actual is True
        assert actual == expected

    def test_has_operator_parity_missing(self) -> None:
        from mypy.checkmember import has_operator

        self._set_active(False)
        try:
            expected = has_operator(self.fx.a, "__add__")
        finally:
            self._set_active(True)
        actual = has_operator(self.fx.a, "__add__")
        assert actual is False
        assert actual == expected

    def test_has_operator_rust_answers_meta_any(self) -> None:
        from mypy.checkmember import has_operator
        from mypy.types import AnyType, TypeOfAny

        # AnyType: Python says True; Rust mirrors it without needing a
        # superclass lookup, so this resolves with no resolver floor.
        assert has_operator(AnyType(TypeOfAny.special_form), "__eq__") is True

    def test_meta_has_operator_rust_answers(self) -> None:
        from mypy.checkmember import meta_has_operator

        # No fixture has a metaclass, so Python's std-lib "type" fallback
        # would crash in this test env. Rust returns Some(false) via the
        # default-metaclass path, so False proves Rust answered.
        assert meta_has_operator(self.fx.a, "__call__") is False

    def test_instance_fallback_parity(self) -> None:
        from mypy.checkmember import instance_fallback

        for t in (self.fx.a, self.fx.lit1):
            self._set_active(False)
            try:
                expected = instance_fallback(t)
            finally:
                self._set_active(True)
            actual = instance_fallback(t)
            assert isinstance(actual, Instance)
            assert actual == expected

    def test_instance_fallback_rust_tuple_parity(self) -> None:
        from mypy.checkmember import instance_fallback
        from mypy.types import TupleType

        cases = [
            # builtins tuple: Python rebuilds the args (join union) while Rust
            # returns the partial fallback unchanged, so only the class must
            # match.
            (TupleType([self.fx.a, self.fx.b], self.fx.std_tuple), self.fx.std_tuplei),
            # non-builtins fallback: both return the partial fallback unchanged.
            (TupleType([self.fx.a], Instance(self.fx.ai, [])), self.fx.ai),
        ]
        for t, expected_info in cases:
            self._set_active(False)
            try:
                expected = instance_fallback(t)
            finally:
                self._set_active(True)
            actual = instance_fallback(t)
            assert isinstance(actual, Instance)
            assert isinstance(expected, Instance)
            assert actual.type is expected_info
            assert expected.type is expected_info

    def test_defined_in_superclass_parity(self) -> None:
        # member_info is captured eagerly when the resolver is built, so a
        # fresh resolver is needed after mutating ai.names.
        from mypy.checkmember import defined_in_superclass
        from mypy.nodes import MDEF, SymbolTableNode, Var

        v = Var("x")
        v.type = self.fx.a
        v.has_explicit_value = True
        self.fx.ai.names["x"] = SymbolTableNode(MDEF, v)
        try:
            local = self._tk.build_native_resolver(
                [self.fx.bi, self.fx.ai, self.fx.oi], []
            )
            self._set_resolver(local)
            self._set_active(False)
            try:
                expected = defined_in_superclass(self.fx.bi, "x")
                expected_missing = defined_in_superclass(self.fx.bi, "zzz")
            finally:
                self._set_active(True)
            assert defined_in_superclass(self.fx.bi, "x") is True
            assert defined_in_superclass(self.fx.bi, "x") == expected
            assert defined_in_superclass(self.fx.bi, "zzz") is False
            assert expected_missing is False
        finally:
            self._set_resolver(self.resolver)
            del self.fx.ai.names["x"]

    def _member_access_expected(
        self, instance: Instance, method: TypeInfo, signature: CallableType
    ) -> Type:
        # Python baseline for the M20 seam tail:
        # map_instance_to_supertype -> expand_type_by_instance -> freeze
        # (checkmember.py:502-504). Runs with the native checkmember gate

        # off so it always exercises the pure-Python expand path.
        from mypy.expandtype import expand_type_by_instance
        from mypy.maptype import map_instance_to_supertype

        self._set_active(False)
        try:
            mapped = map_instance_to_supertype(instance, method)
            expanded = expand_type_by_instance(signature, mapped)
            from mypy.typeops import freeze_all_type_vars

            freeze_all_type_vars(expanded)
            return expanded
        finally:
            self._set_active(True)

    def _rust_member_access(
        self, instance: Type, signature: Type, method_fullname: str
    ) -> bytes | None:
        result = self._tk.rust_analyze_instance_member_access(
            self.resolver,
            self._bytes_of(instance),
            self._bytes_of(signature),
            method_fullname,
            False,
            False,
        )
        return bytes(result) if result is not None else None

    def _assert_parity_callable(self, decoded: Type, expected: Type) -> None:
        # Structural parity for the M20 seam: decoded comes back from the wire
        # with a process-global builtins.function TypeInfo (see
        # instance_cache.function_type in mypy/typeops.py), which is not the

        # TypeFixture() TypeInfo under test. Comparing the whole CallableType
        # by __eq__ would then fail on fallback identity alone, so compare
        # every field except fallback and verify fallback by name only.
        assert isinstance(decoded, CallableType) and isinstance(expected, CallableType)  # type: ignore[misc]
        assert decoded.name == expected.name
        assert decoded.is_ellipsis_args == expected.is_ellipsis_args
        assert decoded.type_guard == expected.type_guard
        assert decoded.type_is == expected.type_is
        assert decoded.arg_types == expected.arg_types
        assert decoded.arg_names == expected.arg_names
        assert decoded.arg_kinds == expected.arg_kinds
        assert decoded.ret_type == expected.ret_type
        assert decoded.fallback.type.fullname == expected.fallback.type.fullname

    def test_instance_member_access_parity_plain(self) -> None:
        # Non-generic static method: member type is just the ret type.
        from mypy.checkmember import _deserialize_type_for_checkmember

        sig = CallableType(
            arg_types=[],
            arg_kinds=[],
            arg_names=[],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        expected = self._member_access_expected(self.fx.ga, self.fx.gi, sig)
        rust_bytes = self._rust_member_access(self.fx.ga, sig, "G")
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(rust_bytes)
        assert isinstance(decoded, ProperType)
        self._assert_parity_callable(decoded, expected)
        assert isinstance(decoded, CallableType)
        assert decoded.ret_type == self.fx.a

    def test_instance_member_access_parity_expands(self) -> None:
        # Generic: G[A].foo() -> G[A] substitutes T`1 into the ret type.
        # Use a namespaced tvar (production keys env on the declaring class
        # fullname, types.py:554) so both sides agree.
        from mypy.checkmember import _deserialize_type_for_checkmember

        ns_t = TypeVarType(
            "T",
            "__main__.T",
            TypeVarId(1, namespace="G"),
            [],
            self.fx.o,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        ret = Instance(self.fx.gi, [ns_t])
        sig = CallableType(
            arg_types=[],
            arg_kinds=[],
            arg_names=[],
            ret_type=ret,
            fallback=self.fx.function,
        )
        expected = self._member_access_expected(self.fx.ga, self.fx.gi, sig)
        rust_bytes = self._rust_member_access(self.fx.ga, sig, "G")
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(rust_bytes)
        assert isinstance(decoded, ProperType)
        self._assert_parity_callable(decoded, expected)
        assert isinstance(decoded, CallableType)
        assert decoded.ret_type == self.fx.ga

    def test_instance_member_access_parity_sibling_class_maps(self) -> None:
        # G2[A].foo() where foo is defined on G2 maps the args onto G2[A]
        # even though the instance type is generic.
        from mypy.checkmember import _deserialize_type_for_checkmember

        sig = CallableType(
            arg_types=[],
            arg_kinds=[],
            arg_names=[],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        instance = Instance(self.fx.g2i, [self.fx.a])
        expected = self._member_access_expected(instance, self.fx.g2i, sig)
        rust_bytes = self._rust_member_access(instance, sig, "G2")
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(rust_bytes)
        assert isinstance(decoded, ProperType)
        self._assert_parity_callable(decoded, expected)
        assert isinstance(decoded, CallableType)
        assert decoded.ret_type == self.fx.a

    def test_instance_member_access_rust_none_for_overloaded(self) -> None:
        item = CallableType(
            arg_types=[],
            arg_kinds=[],
            arg_names=[],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        assert self._rust_member_access(self.fx.ga, Overloaded([item]), "G") is None

    def test_instance_member_access_rust_none_for_non_instance(self) -> None:
        # A non-Instance left operand is not handled: defer.
        sig = CallableType(
            arg_types=[],
            arg_kinds=[],
            arg_names=[],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        result = self._tk.rust_analyze_instance_member_access(
            self.resolver,
            self._bytes_of(self.fx.o),
            self._bytes_of(sig),
            "G",
            False,
            False,
        )
        assert result is None

    def test_instance_member_access_rust_none_for_unknown_class(self) -> None:
        # A method fullname with no resolver floor entry defers.
        sig = CallableType(
            arg_types=[],
            arg_kinds=[],
            arg_names=[],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        result = self._tk.rust_analyze_instance_member_access(
            self.resolver,
            self._bytes_of(self.fx.ga),
            self._bytes_of(sig),
            "NoSuchClass",
            False,
            False,
        )
        assert result is None

    def _rust_member_method(
        self,
        instance: Type,
        signature: Type,
        method_fullname: str,
        self_type: Type,
        name: str = "foo",
    ) -> bytes | None:
        result = self._tk.rust_analyze_member_method(
            self.resolver,
            self._bytes_of(instance),
            self._bytes_of(signature),
            method_fullname,
            self._bytes_of(self_type),
            name,
            False,
            False,
        )
        return bytes(result) if result is not None else None

    def test_member_method_parity_binds_and_expands(self) -> None:
        # Plain non-trivial method on the defining class: Rust binds self
        # and expands class type vars. G[T].foo(self: G[T]) -> G[T].
        from mypy.checkmember import _deserialize_type_for_checkmember

        ns_t = TypeVarType(
            "T",
            "__main__.T",
            TypeVarId(1, namespace="G"),
            [],
            self.fx.o,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        ret = Instance(self.fx.gi, [ns_t])
        sig = CallableType(
            arg_types=[Instance(self.fx.gi, [ns_t]), self.fx.a],
            arg_kinds=[ARG_POS, ARG_POS],
            arg_names=["self", "x"],
            ret_type=ret,
            fallback=self.fx.function,
        )
        rust_bytes = self._rust_member_method(
            self.fx.ga, sig, "G", self.fx.ga
        )
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(rust_bytes)
        assert isinstance(decoded, ProperType)
        assert isinstance(decoded, CallableType)
        # self stripped, is_bound set, G[A] substituted into ret type.
        assert decoded.arg_types == [self.fx.a]
        assert decoded.is_bound
        assert decoded.ret_type == self.fx.ga

    def test_member_method_parity_plain(self) -> None:
        # Non-generic method on the defining class G: receiver G[A] with a
        # concrete self annotation passes the self-arg filter; the shim
        # restores the non-wire fields.
        from mypy.checkmember import _deserialize_type_for_checkmember

        sig = CallableType(
            arg_types=[self.fx.ga, self.fx.b],
            arg_kinds=[ARG_POS, ARG_POS],
            arg_names=["self", "x"],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        rust_bytes = self._rust_member_method(
            self.fx.ga, sig, "G", self.fx.ga
        )
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(rust_bytes)
        assert isinstance(decoded, ProperType)
        assert isinstance(decoded, CallableType)
        assert decoded.arg_types == [self.fx.b]
        assert decoded.is_bound
        assert decoded.ret_type == self.fx.a

    def test_member_method_rust_none_for_classmethod(self) -> None:
        # classmethod true -> defer to Python (needs TypeType wrapping).
        sig = CallableType(
            arg_types=[self.fx.a],
            arg_kinds=[ARG_POS],
            arg_names=["self"],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        result = self._tk.rust_analyze_member_method(
            self.resolver,
            self._bytes_of(self.fx.ga),
            self._bytes_of(sig),
            "G",
            self._bytes_of(self.fx.ga),
            "foo",
            False,
            True,
        )
        assert result is None

    def test_member_method_rust_none_for_foreign_self(self) -> None:
        # self_type not the defining class -> check_self_arg could filter:
        # defer.
        sig = CallableType(
            arg_types=[self.fx.a],
            arg_kinds=[ARG_POS],
            arg_names=["self"],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        result = self._tk.rust_analyze_member_method(
            self.resolver,
            self._bytes_of(self.fx.ga),
            self._bytes_of(sig),
            "G",
            self._bytes_of(self.fx.o),
            "foo",
            False,
            False,
        )
        assert result is None

    def test_member_method_rust_none_for_bindable_noncallable(self) -> None:
        # A non-callable signature cannot be bound: defer.
        result = self._tk.rust_analyze_member_method(
            self.resolver,
            self._bytes_of(self.fx.ga),
            self._bytes_of(self.fx.a),
            "G",
            self._bytes_of(self.fx.ga),
            "foo",
            False,
            False,
        )
        assert result is None

    def test_instance_member_access_trivial_self_binds(self) -> None:
        # Trivial-self method: Rust binds the first arg and marks is_bound.
        from mypy.checkmember import _deserialize_type_for_checkmember

        sig = CallableType(
            arg_types=[self.fx.a, self.fx.o],
            arg_kinds=[ARG_POS, ARG_POS],
            arg_names=["self", "x"],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        rust_bytes = self._tk.rust_analyze_instance_member_access(
            self.resolver,
            self._bytes_of(self.fx.ga),
            self._bytes_of(sig),
            "G",
            False,
            True,
        )
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(bytes(rust_bytes))
        # Bound: first arg dropped, is_bound set.
        expected = CallableType(
            arg_types=[self.fx.o],
            arg_kinds=[ARG_POS],
            arg_names=["x"],
            ret_type=self.fx.a,
            fallback=self.fx.function,
        )
        assert isinstance(decoded, CallableType)
        assert decoded.arg_types == expected.arg_types
        assert decoded.arg_kinds == expected.arg_kinds
        assert decoded.arg_names == expected.arg_names
        assert decoded.is_bound
        assert decoded.ret_type == expected.ret_type

    def test_instance_member_access_trivial_self_expands(self) -> None:
        # Trivial-self generic method: Rust expands then binds. Fixture
        # tvars carry namespace "" while production/Rust key on the
        # instance type_ref, so use a namespaced G signature.
        from mypy.checkmember import _deserialize_type_for_checkmember

        ns_t = TypeVarType(
            "T",
            "__main__.T",
            TypeVarId(1, namespace="G"),
            [],
            self.fx.o,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        sig = CallableType(
            arg_types=[self.fx.a, ns_t],
            arg_kinds=[ARG_POS, ARG_POS],
            arg_names=["self", "x"],
            ret_type=Instance(self.fx.gi, [ns_t]),
            fallback=self.fx.function,
        )
        rust_bytes = self._tk.rust_analyze_instance_member_access(
            self.resolver,
            self._bytes_of(self.fx.ga),
            self._bytes_of(sig),
            "G",
            False,
            True,
        )
        assert rust_bytes is not None
        decoded = _deserialize_type_for_checkmember(bytes(rust_bytes))
        assert isinstance(decoded, CallableType)
        # t binds to A (instance arg of G[A]): arg x: T -> A, ret G[T] -> G[A].
        assert decoded.arg_types == [self.fx.a]
        assert decoded.is_bound
        assert decoded.ret_type == self.fx.ga


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeMemberAccessDispatchSuite(Suite):
    """Parity tests for the #805 method-branch dispatch seam.

    `rust_analyze_instance_member_dispatch` replaces the whole method
    branch of `analyze_instance_member_access` (checkmember.py:634-775):
    freshen, the static/trivial-self tail, and the non-trivial tail.
    Rust reads live node flags and the serialized `method.type`,
    freshens against the shared raw-id counter, and returns
    (next_raw_id, changed, wire bytes). Deferred (None) cases fall
    through to the pure-Python branch. The union seam returns per-item
    results that the Python shim joins via `make_simplified_union`.
    """

    def setUp(self) -> None:
        import type_kernel as _tk
        from librt.internal import WriteBuffer as _WB

        from mypy.checkmember import (
            _set_native_checkmember_active,
            _set_native_checkmember_resolver,
        )
        from mypy.wirefixup import set_wire_typeinfo_map

        self._tk = _tk
        self._WB = _WB
        self._set_active = _set_native_checkmember_active
        self._set_resolver = _set_native_checkmember_resolver
        self.fx = TypeFixture()
        for info in (self.fx.gi, self.fx.g2i, self.fx.hi):
            for tv in info.defn.type_vars:
                tv.id = TypeVarId(tv.id.raw_id, namespace=info.fullname)
        type_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.ci,
            self.fx.di,
            self.fx.ei,
            self.fx.e2i,
            self.fx.e3i,
            self.fx.fi,
            self.fx.f2i,
            self.fx.f3i,
            self.fx.gi,
            self.fx.g2i,
            self.fx.hi,
            self.fx.std_tuplei,
            self.fx.type_typei,
            self.fx.bool_type_info,
            self.fx.str_type_info,
            self.fx.functioni,
        ]
        self.resolver = _tk.build_native_resolver(type_infos, [])
        # Live-node read path (build.py:1518).
        self.resolver.set_live_typeinfo_map({info.fullname: info for info in type_infos})
        self._set_resolver(self.resolver)
        set_wire_typeinfo_map({info.fullname: info for info in type_infos})
        self._set_active(True)

    def tearDown(self) -> None:
        from mypy.wirefixup import set_wire_typeinfo_map

        self.resolver.set_live_typeinfo_map(None)
        set_wire_typeinfo_map(None)
        self._set_resolver(None)
        self._set_active(False)

    def _bytes_of(self, t: Type) -> bytes:
        buf = self._WB()
        t.write(buf)
        return buf.getvalue()

    def _add_method(
        self,
        info: TypeInfo,
        name: str,
        sig: CallableType | Overloaded,
        *,
        is_static: bool = False,
        is_trivial_self: bool = False,
        is_class: bool = False,
        is_final: bool = False,
    ) -> FuncDef:
        from mypy.nodes import MDEF, FuncDef, SymbolTableNode

        fn = FuncDef(name, [], None, None)
        fn.type = sig
        fn.info = info
        fn.is_static = is_static
        fn.is_trivial_self = is_trivial_self
        fn.is_class = is_class
        fn.is_final = is_final
        info.names[name] = SymbolTableNode(MDEF, fn)
        return fn

    def _sig(
        self,
        arg_types: list[Type],
        arg_kinds: list[ArgKind],
        arg_names: list[str | None],
        ret: Type,
        variables: list[TypeVarLikeType] | None = None,
    ) -> CallableType:
        return CallableType(
            arg_types=arg_types,
            arg_kinds=arg_kinds,
            arg_names=arg_names,
            ret_type=ret,
            fallback=self.fx.function,
            variables=variables or [],
            is_bound=False,
        )

    def _dispatch(
        self,
        instance: Instance,
        name: str,
        self_type: Type,
        *,
        preserve: bool = False,
        start_raw_id: int | None = None,
        override: str | None = None,
    ) -> tuple[int, bool, Type | None]:
        from mypy.checkmember import _deserialize_type_for_checkmember

        start = TypeVarId.next_raw_id if start_raw_id is None else start_raw_id
        result = self._tk.rust_analyze_instance_member_dispatch(
            self.resolver,
            self._bytes_of(instance),
            name,
            override,
            self._bytes_of(self_type),
            False,
            preserve,
            start,
            False,
        )
        if result is None:
            return (start, False, None)
        next_raw_id, changed, wire_bytes = result
        decoded = _deserialize_type_for_checkmember(bytes(wire_bytes))
        return (next_raw_id, changed, decoded)

    def _raw_dispatch(self, instance: Instance, name: str) -> tuple[int, bool, bytes] | None:
        return self._tk.rust_analyze_instance_member_dispatch(
            self.resolver,
            self._bytes_of(instance),
            name,
            None,
            self._bytes_of(instance),
            False,
            False,
            100,
            False,
        )

    def test_dispatch_static_non_generic_preserves(self) -> None:
        from mypy.nodes import ARG_POS

        self._add_method(
            self.fx.ai, "m", self._sig([self.fx.o], [ARG_POS], ["x"], self.fx.a), is_static=True
        )
        _next_raw_id, changed, decoded = self._dispatch(self.fx.a, "m", self.fx.a)
        decoded = get_proper_type(decoded)
        assert changed is False
        assert isinstance(decoded, CallableType)
        assert decoded.ret_type == self.fx.a
        assert decoded.is_bound is False

    def test_dispatch_trivial_self_binds(self) -> None:
        from mypy.nodes import ARG_POS

        self._add_method(
            self.fx.ai,
            "m",
            self._sig([self.fx.o, self.fx.a], [ARG_POS, ARG_POS], ["self", "x"], self.fx.a),
            is_trivial_self=True,
        )
        _next_raw_id, changed, decoded = self._dispatch(self.fx.a, "m", self.fx.a)
        decoded = get_proper_type(decoded)
        assert changed is False
        assert isinstance(decoded, CallableType)
        assert decoded.is_bound is True
        assert decoded.arg_types == [self.fx.a]
        assert decoded.ret_type == self.fx.a

    def test_dispatch_non_trivial_same_class_binds(self) -> None:
        from mypy.nodes import ARG_POS

        self._add_method(
            self.fx.ai,
            "m",
            self._sig([self.fx.o, self.fx.a], [ARG_POS, ARG_POS], ["self", "x"], self.fx.a),
        )
        _next_raw_id, changed, decoded = self._dispatch(self.fx.a, "m", self.fx.a)
        decoded = get_proper_type(decoded)
        assert changed is False
        assert isinstance(decoded, CallableType)
        assert decoded.is_bound is True
        assert decoded.arg_types == [self.fx.a]
        assert decoded.ret_type == self.fx.a

    def test_dispatch_static_overloaded_expands(self) -> None:
        from mypy.nodes import ARG_POS

        item1 = self._sig([self.fx.o], [ARG_POS], ["x"], self.fx.a)
        item2 = self._sig([self.fx.a], [ARG_POS], ["x"], self.fx.b)
        self._add_method(self.fx.ai, "m", Overloaded([item1, item2]), is_static=True)
        _next_raw_id, changed, decoded = self._dispatch(self.fx.a, "m", self.fx.a)
        decoded = get_proper_type(decoded)
        assert changed is False
        assert isinstance(decoded, Overloaded)
        assert len(decoded.items) == 2
        assert decoded.items[0].ret_type == self.fx.a
        assert decoded.items[1].ret_type == self.fx.b
        assert decoded.items[0].is_bound is False

    def test_dispatch_freshens_generic_method(self) -> None:
        from mypy.nodes import ARG_POS

        ns_t = TypeVarType(
            "T",
            "__main__.T",
            TypeVarId(1, namespace="G"),
            [],
            self.fx.o,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        self._add_method(
            self.fx.ai,
            "m",
            self._sig([self.fx.o], [ARG_POS], ["x"], ns_t, variables=[ns_t]),
            is_static=True,
        )
        old = TypeVarId.next_raw_id
        try:
            next_raw_id, changed, decoded = self._dispatch(
                self.fx.a, "m", self.fx.a, start_raw_id=old
            )
            decoded = get_proper_type(decoded)
            assert changed is True
            assert next_raw_id == old + 1
            assert isinstance(decoded, CallableType)
            rt = get_proper_type(decoded.ret_type)
            assert isinstance(rt, TypeVarType)
            assert rt.id.raw_id == old
            assert rt.id.meta_level == 1
        finally:
            TypeVarId.next_raw_id = old

    def test_dispatch_defers_unknown_name(self) -> None:
        assert self._raw_dispatch(self.fx.a, "zzz") is None

    def test_dispatch_defers_decorator(self) -> None:
        from mypy.nodes import MDEF, Decorator, FuncDef, SymbolTableNode, Var

        fn = FuncDef("m", [], None, None)
        fn.type = self._sig([], [], [], self.fx.a)
        self.fx.ai.names["m"] = SymbolTableNode(MDEF, Decorator(fn, [], Var("m")))
        assert self._raw_dispatch(self.fx.a, "m") is None

    def test_dispatch_defers_var_node(self) -> None:
        from mypy.nodes import MDEF, SymbolTableNode, Var

        self.fx.ai.names["m"] = SymbolTableNode(MDEF, Var("m"))
        assert self._raw_dispatch(self.fx.a, "m") is None

    def test_dispatch_defers_subclass_receiver(self) -> None:
        from mypy.nodes import ARG_POS

        self._add_method(
            self.fx.ai, "m", self._sig([self.fx.o], [ARG_POS], ["x"], self.fx.a)
        )
        assert self._raw_dispatch(self.fx.c, "m") is None

    def test_dispatch_defers_non_final_init(self) -> None:
        from mypy.nodes import ARG_POS

        self._add_method(
            self.fx.ai, "__init__", self._sig([self.fx.o], [ARG_POS], ["self"], NoneType())
        )
        assert self._raw_dispatch(self.fx.a, "__init__") is None

    def test_union_seam_per_item(self) -> None:
        from mypy.checkmember import _deserialize_type_for_checkmember

        self._add_method(self.fx.ai, "m", self._sig([], [], [], self.fx.a), is_static=True)
        self._add_method(self.fx.bi, "m", self._sig([], [], [], self.fx.b), is_static=True)
        union = UnionType([self.fx.a, self.fx.b])
        result = self._tk.rust_analyze_union_member_access(
            self.resolver,
            self._bytes_of(union),
            "m",
            False,
            False,
            False,
            True,
            100,
            False,
        )
        assert result is not None
        _next_raw_id, changed, per_item = result
        assert changed is False
        assert len(per_item) == 2
        decoded = [_deserialize_type_for_checkmember(bytes(b)) for b in per_item]
        assert isinstance(decoded[0], CallableType) and isinstance(decoded[1], CallableType)
        assert decoded[0].ret_type == self.fx.a
        assert decoded[1].ret_type == self.fx.b

    def test_union_seam_defers_for_lvalue(self) -> None:
        union = UnionType([self.fx.a, self.fx.b])
        result = self._tk.rust_analyze_union_member_access(
            self.resolver,
            self._bytes_of(union),
            "m",
            True,
            False,
            False,
            True,
            100,
            False,
        )
        assert result is None


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCheckmemberDeferralSuite(Suite):
    """Reduction of `analyze_member_access_inner` fallback-recursion defers (#872).

    The general member-access seam previously deferred every TupleType /
    LiteralType / CallableType / TypeVar fallback that resolved to an
    Instance (`memacc:tuple_instance_fb` and friends, the largest
    wire-portable defer class in checkmember.rs). It now routes rvalue,
    non-super Instance fallbacks through the native method branch, so
    e.g. `(a, b).method(...)` type-checks without falling back to Python.

    Each test calls the seam directly: a TupleType-with-method-fallback
    must answer natively (non-None, bound method); lvalue/super operands,
    and fallbacks without a dispatch context, must still defer (None).
    """

    def setUp(self) -> None:
        import type_kernel as _tk
        from librt.internal import WriteBuffer as _WB

        from mypy.checkmember import (
            _set_native_checkmember_active,
            _set_native_checkmember_resolver,
        )
        from mypy.wirefixup import set_wire_typeinfo_map

        self._tk = _tk
        self._WB = _WB
        self.fx = TypeFixture()
        type_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.ci,
            self.fx.str_type_info,
            self.fx.functioni,
        ]
        self.resolver = _tk.build_native_resolver(type_infos, [])
        self.resolver.set_live_typeinfo_map({info.fullname: info for info in type_infos})
        _set_native_checkmember_resolver(self.resolver)
        set_wire_typeinfo_map({info.fullname: info for info in type_infos})
        _set_native_checkmember_active(True)

    def tearDown(self) -> None:
        from mypy.checkmember import (
            _set_native_checkmember_active,
            _set_native_checkmember_resolver,
        )
        from mypy.wirefixup import set_wire_typeinfo_map

        self.resolver.set_live_typeinfo_map(None)
        set_wire_typeinfo_map(None)
        _set_native_checkmember_resolver(None)
        _set_native_checkmember_active(False)

    def _bytes_of(self, t: Type) -> bytes:
        buf = self._WB()
        t.write(buf)
        return buf.getvalue()

    def _add_method(
        self, info: TypeInfo, name: str, sig: CallableType, is_trivial_self: bool = False
    ) -> None:
        from mypy.nodes import MDEF, FuncDef, SymbolTableNode

        fn = FuncDef(name, [], None, None)
        fn.type = sig
        fn.info = info
        fn.is_trivial_self = is_trivial_self
        info.names[name] = SymbolTableNode(MDEF, fn)

    def _general(
        self,
        typ: Type,
        name: str,
        *,
        is_lvalue: bool = False,
        is_super: bool = False,
        start: int = 100,
    ) -> tuple[int, bool, Type | None]:
        from mypy.checkmember import _deserialize_type_for_checkmember

        result = self._tk.rust_analyze_member_access(
            self.resolver,
            name,
            self._bytes_of(typ),
            self._bytes_of(typ),
            is_lvalue,
            is_super,
            False,
            start,
            False,
        )
        if result is None:
            return (start, False, None)
        next_raw_id, changed, wire_bytes = result
        decoded = _deserialize_type_for_checkmember(bytes(wire_bytes))
        return (next_raw_id, changed, decoded)

    def test_tuple_fallback_routes_and_binds(self) -> None:
        # class A gains a trivial-self method m(self, x: int) -> A; a
        # TupleType with fallback A must recurse into the native method
        # branch and return the bound signature (self stripped).
        from mypy.nodes import ARG_POS
        from mypy.types import TupleType

        self._add_method(
            self.fx.ai,
            "m",
            CallableType(
                [self.fx.o, self.fx.a],
                [ARG_POS, ARG_POS],
                ["self", "x"],
                self.fx.a,
                self.fx.function,
            ),
            is_trivial_self=True,
        )
        tup = TupleType([self.fx.a], self.fx.a)
        _next_raw_id, changed, decoded = self._general(tup, "m")
        decoded = get_proper_type(decoded)
        assert changed is False
        assert isinstance(decoded, CallableType)
        assert decoded.is_bound is True
        assert decoded.arg_types == [self.fx.a]
        assert decoded.ret_type == self.fx.a

    def test_tuple_fallback_lvalue_defers(self) -> None:
        # An lvalue access must defer (Python owns lvalue semantics).
        from mypy.nodes import ARG_POS
        from mypy.types import TupleType

        self._add_method(
            self.fx.ai,
            "m",
            CallableType(
                [self.fx.o], [ARG_POS], ["self"], self.fx.a, self.fx.function
            ),
            is_trivial_self=True,
        )
        tup = TupleType([self.fx.a], self.fx.a)
        assert self._general(tup, "m", is_lvalue=True)[2] is None
        assert self._general(tup, "m", is_super=True)[2] is None

    def test_tuple_fallback_no_method_defers(self) -> None:
        # A fallback Instance with no matching method defers (Python
        # reports the missing-attribute diagnostic); the recursion still
        # routes without guessing.
        from mypy.types import TupleType

        tup = TupleType([self.fx.a], self.fx.a)
        assert self._general(tup, "missing_name")[2] is None


